import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(2.5, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Load image texture
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);
  imageTexture.colorSpace = THREE.SRGBColorSpace;

  // Main image plane (512x320 → 1.0 × 0.625 aspect)
  const geometry = new THREE.PlaneGeometry(1, 0.625);
  const material = new THREE.MeshBasicMaterial({
    map: imageTexture,
    transparent: true,
    side: THREE.FrontSide
  });
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Accent border mesh (for focus/hover effect)
  const borderGeometry = new THREE.PlaneGeometry(1.05, 0.656);
  const borderMaterial = new THREE.MeshBasicMaterial({
    color: 0xff2a38, // accent red
    transparent: true,
    opacity: 0,
    depthWrite: false,
    side: THREE.FrontSide
  });
  const borderMesh = new THREE.Mesh(borderGeometry, borderMaterial);
  borderMesh.position.z = -0.01;
  group.add(borderMesh);

  // Track all active timelines for cleanup
  const timelines = [];

  const handlers = {
    onHover: () => {
      timelines.forEach(t => t.kill());
      timelines.length = 0;

      // Rise-in animation: y +0.15, power3.out, 0.7s
      const riseTimeline = gsap.to(group.position, {
        y: group.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out'
      });
      timelines.push(riseTimeline);

      // Accent border reveals
      const borderTimeline = gsap.to(borderMaterial, {
        opacity: 0.3,
        duration: 0.4,
        ease: 'power2.out'
      });
      timelines.push(borderTimeline);
    },

    onHoverEnd: () => {
      timelines.forEach(t => t.kill());
      timelines.length = 0;

      // Settle back
      const settleTimeline = gsap.to(group.position, {
        y: 1.6,
        duration: 0.5,
        ease: 'power2.inOut'
      });
      timelines.push(settleTimeline);

      // Border fades
      const borderTimeline = gsap.to(borderMaterial, {
        opacity: 0,
        duration: 0.3,
        ease: 'power2.out'
      });
      timelines.push(borderTimeline);
    },

    onClick: () => {
      timelines.forEach(t => t.kill());
      timelines.length = 0;

      // Press-down: scale 0.97, back.out 120ms, then spring back
      const pressTimeline = gsap.timeline();
      pressTimeline.to(group.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out'
      }, 0)
      .to(group.scale, {
        x: 1,
        y: 1,
        duration: 0.2,
        ease: 'elastic.out'
      }, 0.12);

      timelines.push(pressTimeline);
    }
  };

  group.userData.handlers = handlers;

  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    timelines.length = 0;
    geometry.dispose();
    material.dispose();
    borderGeometry.dispose();
    borderMaterial.dispose();
    imageTexture.dispose();
  };

  return group;
}
